arguments.file_text:
:root {
  --bg: #0b0d10;
  --bg-elev: #14181d;
  --bg-elev-2: #1b2026;
  --border: #2a3038;
  --border-strong: #3a4250;
  --text: #f1f3f5;
  --text-muted: #b8bfc7;
  --text-dim: #8a939e;
  --accent: #ffb347;
  --accent-hover: #ffc067;
  --accent-ink: #1a1207;
  --danger: #ff6b6b;
  --success: #6dd49a;
  --focus: #7cc4ff;
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 6px 24px rgba(0, 0, 0, 0.45);
  --maxw: 1240px;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
html { color-scheme: dark; }
body {
  font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; }
a:focus-visible,
button:focus-visible,
input:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.skip-link {
  position: absolute;
  left: 8px;
  top: -40px;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  z-index: 1000;
  text-decoration: none;
}
.skip-link:focus {
  top: 8px;
}

.container {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 24px;
}

/* ================ Header ================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(11, 13, 16, 0.85);
  backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--border);
}
.announcement {
  background: var(--bg-elev-2);
  color: var(--text-muted);
  font-size: 0.85rem;
  text-align: center;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border);
}
.announcement strong { color: var(--accent); }

.header-inner {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 14px 24px;
  max-width: var(--maxw);
  margin: 0 auto;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 1.1rem;
  text-decoration: none;
  letter-spacing: 0.02em;
}
.brand-mark {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), #ff7a59);
  display: grid;
  place-items: center;
  color: var(--accent-ink);
  font-weight: 900;
}

.primary-nav { flex: 1; }
.primary-nav ul {
  display: flex;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  text-decoration: none;
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.95rem;
}
.primary-nav a:hover { color: var(--text); background: var(--bg-elev); }
.primary-nav a[aria-current="page"] { color: var(--text); background: var(--bg-elev); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.search {
  display: flex;
  align-items: center;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 6px 12px;
  gap: 8px;
  min-width: 220px;
}
.search:focus-within {
  border-color: var(--border-strong);
  outline: 2px solid var(--focus);
  outline-offset: 1px;
}
.search input {
  background: transparent;
  border: 0;
  color: var(--text);
  font-size: 0.9rem;
  width: 100%;
  outline: none;
}
.search input::placeholder { color: var(--text-dim); }
.search svg { color: var(--text-dim); flex-shrink: 0; }

.icon-btn {
  position: relative;
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-muted);
  width: 40px;
  height: 40px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  cursor: pointer;
}
.icon-btn:hover { color: var(--text); background: var(--bg-elev); }
.icon-btn .badge {
  position: absolute;
  top: 4px;
  right: 4px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 0.65rem;
  font-weight: 700;
  border-radius: 999px;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  display: grid;
  place-items: center;
  border: 2px solid var(--bg);
}

/* ================ Hero ================ */
.hero {
  position: relative;
  padding: 64px 0 48px;
  border-bottom: 1px solid var(--border);
  overflow: hidden;
}
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(60% 60% at 80% 20%, rgba(255, 179, 71, 0.18), transparent 60%),
    radial-gradient(50% 50% at 10% 80%, rgba(124, 196, 255, 0.12), transparent 60%);
  pointer-events: none;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 48px;
  align-items: center;
  position: relative;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent);
  background: rgba(255, 179, 71, 0.1);
  border: 1px solid rgba(255, 179, 71, 0.3);
  padding: 6px 12px;
  border-radius: 999px;
}
.hero h1 {
  font-size: clamp(2rem, 4.6vw, 3.6rem);
  line-height: 1.05;
  margin: 18px 0 16px;
  letter-spacing: -0.02em;
}
.hero h1 em {
  font-style: normal;
  background: linear-gradient(135deg, var(--accent), #ff7a59);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hero p.lede {
  color: var(--text-muted);
  max-width: 52ch;
  font-size: 1.05rem;
  margin: 0 0 28px;
}
.hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 20px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 0.95rem;
  text-decoration: none;
  cursor: pointer;
  border: 1px solid transparent;
  background: var(--bg-elev);
  color: var(--text);
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}
.btn:hover { background: var(--bg-elev-2); }
.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover { background: var(--accent-hover); }
.btn-ghost {
  background: transparent;
  border-color: var(--border-strong);
  color: var(--text);
}
.btn-ghost:hover { border-color: var(--text); }

.hero-stats {
  margin-top: 36px;
  display: flex;
  gap: 36px;
  flex-wrap: wrap;
}
.stat .num {
  display: block;
  font-size: 1.6rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.stat .label {
  display: block;
  font-size: 0.85rem;
  color: var(--text-dim);
}

.hero-card {
  position: relative;
  border-radius: var(--radius);
  background: linear-gradient(160deg, #1f2731, #11151a);
  border: 1px solid var(--border);
  padding: 24px;
  box-shadow: var(--shadow);
  aspect-ratio: 4 / 5;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
}
.hero-card::after {
  content: "";
  position: absolute;
  inset: -40% -10% auto auto;
  width: 70%;
  height: 70%;
  background: radial-gradient(closest-side, rgba(255,179,71,0.45), transparent 70%);
  filter: blur(10px);
  pointer-events: none;
}
.hero-card .product-illu {
  position: relative;
  z-index: 1;
  flex: 1;
  display: grid;
  place-items: center;
  font-size: clamp(8rem, 18vw, 14rem);
  filter: drop-shadow(0 14px 28px rgba(0,0,0,0.6));
}
.hero-card .meta {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
}
.hero-card .meta h2 {
  margin: 0 0 4px;
  font-size: 1.1rem;
  letter-spacing: -0.01em;
}
.hero-card .meta p {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.9rem;
}
.hero-card .price {
  font-weight: 800;
  font-size: 1.2rem;
  color: var(--accent);
  white-space: nowrap;
}

/* ================ Sections ================ */
section { padding: 64px 0; }
section + section { border-top: 1px solid var(--border); }

.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}
.section-head h2 {
  font-size: clamp(1.5rem, 2.6vw, 2rem);
  margin: 0;
  letter-spacing: -0.02em;
}
.section-head p {
  margin: 6px 0 0;
  color: var(--text-muted);
  max-width: 60ch;
}
.section-link {
  color: var(--accent);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
}
.section-link:hover { text-decoration: underline; }

/* Categories */
.categories {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.category-card {
  display: block;
  text-decoration: none;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  color: var(--text);
  transition: transform 0.15s, border-color 0.15s, background 0.15s;
}
.category-card:hover {
  background: var(--bg-elev-2);
  border-color: var(--border-strong);
  transform: translateY(-2px);
}
.category-card .ico {
  font-size: 2rem;
  margin-bottom: 10px;
}
.category-card h3 {
  margin: 0 0 4px;
  font-size: 1rem;
}
.category-card p {
  margin: 0;
  font-size: 0.85rem;
  color: var(--text-dim);
}

/* Tabs */
.tabs {
  display: flex;
  gap: 4px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  padding: 4px;
  border-radius: 999px;
  width: fit-content;
}
.tab {
  background: transparent;
  border: 0;
  color: var(--text-muted);
  padding: 8px 16px;
  border-radius: 999px;
  font-weight: 500;
  font-size: 0.9rem;
  cursor: pointer;
}
.tab[aria-selected="true"] {
  background: var(--bg-elev-2);
  color: var(--text);
}
.tab:hover:not([aria-selected="true"]) { color: var(--text); }

/* Products grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.product-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.15s, border-color 0.15s;
}
.product-card:hover {
  transform: translateY(-2px);
  border-color: var(--border-strong);
}
.product-media {
  position: relative;
  aspect-ratio: 1 / 1;
  background: linear-gradient(160deg, #1f2731, #0f1318);
  display: grid;
  place-items: center;
  font-size: 5rem;
  overflow: hidden;
}
.product-media .tag {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--bg);
  color: var(--text);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 4px 8px;
  border-radius: 999px;
  border: 1px solid var(--border-strong);
}
.product-media .tag.sale { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
.product-media .tag.new { background: var(--success); color: #07210f; border-color: transparent; }

.wishlist {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 36px;
  height: 36px;
  border-radius: 999px;
  background: rgba(11,13,16,0.65);
  border: 1px solid var(--border);
  color: var(--text);
  cursor: pointer;
  display: grid;
  place-items: center;
}
.wishlist[aria-pressed="true"] { color: var(--danger); }
.wishlist:hover { background: var(--bg-elev-2); }

.product-body {
  padding: 14px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.product-cat {
  font-size: 0.75rem;
  color: var(--text-dim);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.product-title {
  margin: 0;
  font-size: 0.98rem;
  font-weight: 600;
  letter-spacing: -0.005em;
}
.product-title a { text-decoration: none; }
.product-title a:hover { color: var(--accent); }
.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  color: var(--text-muted);
}
.stars { color: var(--accent); letter-spacing: 1px; }

.product-foot {
  margin-top: auto;
  padding-top: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.price-block { display: flex; align-items: baseline; gap: 8px; }
.price-now {
  font-weight: 800;
  font-size: 1.05rem;
}
.price-was {
  color: var(--text-dim);
  text-decoration: line-through;
  font-size: 0.85rem;
}

.add-btn {
  border: 1px solid var(--border-strong);
  background: var(--bg-elev-2);
  color: var(--text);
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 0.85rem;
  cursor: pointer;
}
.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: transparent; }

/* Deals */
.deals {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 20px;
}
.deal {
  position: relative;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  padding: 28px;
  min-height: 260px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  text-decoration: none;
  color: var(--text);
  overflow: hidden;
  background: var(--bg-elev);
}
.deal::before {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--deal-bg, linear-gradient(135deg, #1f2731, #0f1318));
  z-index: 0;
}
.deal::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 30%, rgba(0,0,0,0.55));
  z-index: 0;
}
.deal > * { position: relative; z-index: 1; }
.deal-large { grid-row: span 2; }
.deal h3 {
  margin: 0;
  font-size: clamp(1.3rem, 2vw, 1.8rem);
  letter-spacing: -0.02em;
}
.deal p {
  margin: 6px 0 0;
  color: var(--text-muted);
  max-width: 36ch;
}
.deal .deal-tag {
  display: inline-block;
  align-self: flex-start;
  background: rgba(255,255,255,0.1);
  backdrop-filter: blur(4px);
  border: 1px solid rgba(255,255,255,0.18);
  color: #fff;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 12px;
}
.deal:hover { transform: translateY(-2px); border-color: var(--border-strong); }
.deal-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 600;
  color: var(--accent);
}

.countdown {
  display: flex;
  gap: 8px;
  margin-top: 16px;
}
.countdown-cell {
  background: rgba(0,0,0,0.5);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 8px;
  padding: 8px 10px;
  min-width: 56px;
  text-align: center;
}
.countdown-cell .n {
  display: block;
  font-weight: 800;
  font-size: 1.2rem;
  font-variant-numeric: tabular-nums;
}
.countdown-cell .l {
  font-size: 0.7rem;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

/* Editorial */
.editorial {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.article-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.article-media {
  aspect-ratio: 16 / 10;
  background: linear-gradient(135deg, var(--c1, #2c3440), var(--c2, #14181d));
  display: grid;
  place-items: center;
  font-size: 4rem;
  position: relative;
}
.article-media .pill {
  position: absolute;
  top: 14px;
  left: 14px;
  background: rgba(11,13,16,0.7);
  border: 1px solid var(--border-strong);
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text);
}
.article-body { padding: 18px 20px 22px; flex: 1; display: flex; flex-direction: column; gap: 8px; }
.article-meta {
  font-size: 0.8rem;
  color: var(--text-dim);
}
.article-body h3 {
  margin: 0;
  font-size: 1.1rem;
  letter-spacing: -0.01em;
}
.article-body h3 a { text-decoration: none; }
.article-body h3 a:hover { color: var(--accent); }
.article-body p {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.92rem;
}
.article-body .read-more {
  margin-top: auto;
  padding-top: 8px;
  font-weight: 600;
  color: var(--accent);
  text-decoration: none;
  font-size: 0.9rem;
}

/* Newsletter */
.newsletter {
  background: linear-gradient(135deg, #1a2028, #11151a);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 40px;
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 32px;
  align-items: center;
}
.newsletter h2 { margin: 0 0 8px; font-size: clamp(1.3rem, 2.2vw, 1.7rem); letter-spacing: -0.02em; }
.newsletter p { margin: 0; color: var(--text-muted); }
.newsletter form {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.newsletter .row {
  display: flex;
  gap: 8px;
}
.newsletter input[type="email"] {
  flex: 1;
  background: var(--bg);
  border: 1px solid var(--border-strong);
  color: var(--text);
  padding: 12px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  min-width: 0;
}
.newsletter input[type="email"]::placeholder { color: var(--text-dim); }
