+}
+.search input {
+  background: transparent;
+  border: 0;
+  color: var(--text);
+  font-size: 0.9rem;
+  width: 100%;
+  outline: none;
+}
+.search input::placeholder { color: var(--text-dim); }
+.search svg { color: var(--text-dim); flex-shrink: 0; }
+
+.icon-btn {
+  position: relative;
+  background: transparent;
+  border: 1px solid transparent;
+  color: var(--text-muted);
+  width: 40px;
+  height: 40px;
