+  color: var(--accent-ink);
+}
+.btn-primary:hover { background: var(--accent-hover); }
+.btn-ghost {
+  background: transparent;
+  border-color: var(--border-strong);
+  color: var(--text);
+}
+.btn-ghost:hover { border-color: var(--text); }
+
+.hero-stats {
+  margin-top: 36px;
+  display: flex;
+  gap: 36px;
+  flex-wrap: wrap;
+}
+.stat .num {
+  display: block;
+  font-size: 1.6rem;
+  font-weight: 800;
+  letter-spacing: -0.02em;
+}
+.stat .label {
+  display: block;
+  font-size: 0.85rem;
+  color: var(--text-dim);
+}
+
+.hero-card {
+  position: relative;
+  border-radius: var(--radius);
+  background: linear-gradient(160deg, #1f2731, #11151a);
+  border: 1px solid var(--border);
+  padding: 24px;
+  box-shadow: var(--shadow);
+  aspect-ratio: 4 / 5;
+  display: flex;
+  flex-direction: column;
+  justify-content: space-between;
+  overflow: hidden;
+}
+.hero-card::after {
+  content: "";
+  position: absolute;
+  inset: -40% -10% auto auto;
+  width: 70%;
+  height: 70%;
+  background: radial-gradient(closest-side, rgba(255,179,71,0.45), transparent 70%);
