+.hero-card .meta {
+  position: relative;
+  z-index: 1;
+  display: flex;
+  align-items: end;
+  justify-content: space-between;
+  gap: 12px;
+}
+.hero-card .meta h2 {
+  margin: 0 0 4px;
+  font-size: 1.1rem;
