+}
+.category-card:hover {
+  background: var(--bg-elev-2);
+  border-color: var(--border-strong);
+  transform: translateY(-2px);
+}
+.category-card .ico {
+  font-size: 2rem;
+  margin-bottom: 10px;
+}
+.category-card h3 {
+  margin: 0 0 4px;
+  font-size: 1rem;
+}
+.category-card p {
+  margin: 0;
+  font-size: 0.85rem;
+  color: var(--text-dim);
+}
+
+/* Tabs */
+.tabs {
+  display: flex;
+  gap: 4px;
+  background: var(--bg-elev);
+  border: 1px solid var(--border);
+  padding: 4px;
+  border-radius: 999px;
+  width: fit-content;
+}
+.tab {
+  background: transparent;
+  border: 0;
+  color: var(--text-muted);
+  padding: 8px 16px;
+  border-radius: 999px;
+  font-weight: 500;
+  font-size: 0.9rem;
+  cursor: pointer;
+}
+.tab[aria-selected="true"] {
+  background: var(--bg-elev-2);
+  color: var(--text);
+}
+.tab:hover:not([aria-selected="true"]) { color: var(--text); }
+
+/* Products grid */
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 20px;
+}
+
+.product-card {
+  background: var(--bg-elev);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: transform 0.15s, border-color 0.15s;
+}
+.product-card:hover {
+  transform: translateY(-2px);
+  border-color: var(--border-strong);
+}
+.product-media {
+  position: relative;
+  aspect-ratio: 1 / 1;
+  background: linear-gradient(160deg, #1f2731, #0f1318);
+  display: grid;
+  place-items: center;
+  font-size: 5rem;
+  overflow: hidden;
+}
+.product-media .tag {
+  position: absolute;
+  top: 12px;
+  left: 12px;
+  background: var(--bg);
+  color: var(--text);
+  font-size: 0.72rem;
+  font-weight: 700;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  padding: 4px 8px;
+  border-radius: 999px;
+  border: 1px solid var(--border-strong);
+}
+.product-media .tag.sale { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
+.product-media .tag.new { background: var(--success); color: #07210f; border-color: transparent; }
+
+.wishlist {
+  position: absolute;
+  top: 10px;
+  right: 10px;
+  width: 36px;
+  height: 36px;
+  border-radius: 999px;
+  background: rgba(11,13,16,0.65);
+  border: 1px solid var(--border);
+  color: var(--text);
+  cursor: pointer;
+  display: grid;
+  place-items: center;
+}
+.wishlist[aria-pressed="true"] { color: var(--danger); }
+.wishlist:hover { background: var(--bg-elev-2); }
+
+.product-body {
+  padding: 14px 16px 16px;
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+  flex: 1;
+}
+.product-cat {
+  font-size: 0.75rem;
+  color: var(--text-dim);
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+}
+.product-title {
+  margin: 0;
+  font-size: 0.98rem;
+  font-weight: 600;
+  letter-spacing: -0.005em;
+}
+.product-title a { text-decoration: none; }
+.product-title a:hover { color: var(--accent); }
+.product-rating {
+  display: flex;
+  align-items: center;
+  gap: 6px;
+  font-size: 0.82rem;
+  color: var(--text-muted);
+}
+.stars { color: var(--accent); letter-spacing: 1px; }
+
+.product-foot {
+  margin-top: auto;
+  padding-top: 10px;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 10px;
+}
+.price-block { display: flex; align-items: baseline; gap: 8px; }
+.price-now {
+  font-weight: 800;
+  font-size: 1.05rem;
+}
+.price-was {
+  color: var(--text-dim);
+  text-decoration: line-through;
+  font-size: 0.85rem;
+}
+
+.add-btn {
+  border: 1px solid var(--border-strong);
+  background: var(--bg-elev-2);
+  color: var(--text);
+  padding: 8px 12px;
+  border-radius: var(--radius-sm);
+  font-weight: 600;
+  font-size: 0.85rem;
+  cursor: pointer;
+}
+.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
+
+/* Deals */
+.deals {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr;
+  gap: 20px;
+}
+.deal {
+  position: relative;
+  border-radius: var(--radius);
+  border: 1px solid var(--border);
+  padding: 28px;
+  min-height: 260px;
+  display: flex;
+  flex-direction: column;
+  justify-content: space-between;
+  text-decoration: none;
+  color: var(--text);
+  overflow: hidden;
+  background: var(--bg-elev);
+}
+.deal::before {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: var(--deal-bg, linear-gradient(135deg, #1f2731, #0f1318));
+  z-index: 0;
+}
+.deal::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(180deg, transparent 30%, rgba(0,0,0,0.55));
+  z-index: 0;
+}
+.deal > * { position: relative; z-index: 1; }
+.deal-large { grid-row: span 2; }
+.deal h3 {
+  margin: 0;
+  font-size: clamp(1.3rem, 2vw, 1.8rem);
+  letter-spacing: -0.02em;
+}
+.deal p {
+  margin: 6px 0 0;
+  color: var(--text-muted);
+  max-width: 36ch;
+}
+.deal .deal-tag {
+  display: inline-block;
+  align-self: flex-start;
+  background: rgba(255,255,255,0.1);
+  backdrop-filter: blur(4px);
+  border: 1px solid rgba(255,255,255,0.18);
+  color: #fff;
+  padding: 4px 10px;
+  border-radius: 999px;
+  font-size: 0.78rem;
+  font-weight: 600;
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  margin-bottom: 12px;
+}
+.deal:hover { transform: translateY(-2px); border-color: var(--border-strong); }
+.deal-cta {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  font-weight: 600;
+  color: var(--accent);
+}
+
+.countdown {
+  display: flex;
+  gap: 8px;
+  margin-top: 16px;
+}
+.countdown-cell {
+  background: rgba(0,0,0,0.5);
+  border: 1px solid rgba(255,255,255,0.1);
+  border-radius: 8px;
+  padding: 8px 10px;
+  min-width: 56px;
+  text-align: center;
+}
+.countdown-cell .n {
+  display: block;
+  font-weight: 800;
+  font-size: 1.2rem;
+  font-variant-numeric: tabular-nums;
+}
+.countdown-cell .l {
+  font-size: 0.7rem;
+  color: var(--text-dim);
+  text-transform: uppercase;
+  letter-spacing: 0.1em;
+}
+
+/* Editorial */
+.editorial {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 20px;
+}
+.article-card {
+  background: var(--bg-elev);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+}
+.article-media {
+  aspect-ratio: 16 / 10;
+  background: linear-gradient(135deg, var(--c1, #2c3440), var(--c2, #14181d));
+  display: grid;
+  place-items: center;
+  font-size: 4rem;
+  position: relative;
+}
+.article-media .pill {
+  position: absolute;
+  top: 14px;
+  left: 14px;
+  background: rgba(11,13,16,0.7);
+  border: 1px solid var(--border-strong);
+  padding: 4px 10px;
+  border-radius: 999px;
+  font-size: 0.75rem;
+  font-weight: 600;
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  color: var(--text);
+}
+.article-body { padding: 18px 20px 22px; flex: 1; display: flex; flex-direction: column; gap: 8px; }
+.article-meta {
+  font-size: 0.8rem;
+  color: var(--text-dim);
+}
+.article-body h3 {
+  margin: 0;
+  font-size: 1.1rem;
+  letter-spacing: -0.01em;
+}
+.article-body h3 a { text-decoration: none; }
+.article-body h3 a:hover { color: var(--accent); }
+.article-body p {
+  margin: 0;
+  color: var(--text-muted);
+  font-size: 0.92rem;
+}
+.article-body .read-more {
+  margin-top: auto;
+  padding-top: 8px;
+  font-weight: 600;
+  color: var(--accent);
+  text-decoration: none;
+  font-size: 0.9rem;
+}
+
+/* Newsletter */
+.newsletter {
+  background: linear-gradient(135deg, #1a2028, #11151a);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  padding: 40px;
+  display: grid;
+  grid-template-columns: 1.2fr 1fr;
+  gap: 32px;
+  align-items: center;
+}
+.newsletter h2 { margin: 0 0 8px; font-size: clamp(1.3rem, 2.2vw, 1.7rem); letter-spacing: -0.02em; }
+.newsletter p { margin: 0; color: var(--text-muted); }
+.newsletter form {
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+}
+.newsletter .row {
+  display: flex;
+  gap: 8px;
+}
+.newsletter input[type="email"] {
+  flex: 1;
+  background: var(--bg);
+  border: 1px solid var(--border-strong);
+  color: var(--text);
+  padding: 12px 14px;
+  border-radius: var(--radius-sm);
+  font-size: 0.95rem;
+  min-width: 0;
+}
+.newsletter input[type="email"]::placeholder { color: var(--text-dim); }
+.newsletter input[type="email"][aria-invalid="true"] {
+  border-color: var(--danger);
+}
+.field-help { font-size: 0.82rem; color: var(--text-dim); }
+.field-error { font-size: 0.85rem; color: var(--danger); min-height: 1.2em; }
+.newsletter-status {
+  font-size: 0.9rem;
+  color: var(--success);
+  min-height: 1.2em;
+}
+
+/* Footer */
+.site-footer {
+  background: var(--bg-elev);
+  border-top: 1px solid var(--border);
+  padding: 56px 0 24px;
+  margin-top: 32px;
+}
+.footer-grid {
+  display: grid;
+  grid-template-columns: 1.4fr repeat(4, 1fr);
+  gap: 32px;
+}
+.footer-grid h4 {
+  font-size: 0.9rem;
+  text-transform: uppercase;
+  letter-spacing: 0.1em;
+  color: var(--text);
+  margin: 0 0 14px;
+}
+.footer-grid ul { list-style: none; padding: 0; margin: 0; }
+.footer-grid li { margin-bottom: 8px; }
+.footer-grid a {
+  text-decoration: none;
+  color: var(--text-muted);
+  font-size: 0.92rem;
+}
+.footer-grid a:hover { color: var(--text); }
+.footer-grid .about p { color: var(--text-muted); font-size: 0.92rem; }
+.socials { display: flex; gap: 8px; margin-top: 14px; }
+.socials a {
+  width: 36px;
+  height: 36px;
+  border-radius: 999px;
+  border: 1px solid var(--border-strong);
+  display: grid;
+  place-items: center;
+  color: var(--text-muted);
+}
+.socials a:hover { color: var(--text); border-color: var(--text); }
+.footer-bottom {
+  margin-top: 36px;
+  padding-top: 20px;
+  border-top: 1px solid var(--border);
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  flex-wrap: wrap;
+  gap: 12px;
+  color: var(--text-dim);
+  font-size: 0.85rem;
+}
+
+/* Visually hidden */
+.sr-only {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0,0,0,0);
+  white-space: nowrap;
+  border: 0;
+}
+
+/* Reflow / responsive */
+@media (max-width: 1024px) {
+  .product-grid { grid-template-columns: repeat(3, 1fr); }
+  .categories { grid-template-columns: repeat(4, 1fr); }
+  .deals { grid-template-columns: 1fr 1fr; }
+  .deal-large { grid-column: span 2; grid-row: auto; }
+  .editorial { grid-template-columns: repeat(2, 1fr); }
+  .footer-grid { grid-template-columns: 1.4fr repeat(2, 1fr); }
+  .hero-grid { grid-template-columns: 1fr; gap: 32px; }
+  .hero-card { max-width: 420px; aspect-ratio: 5/4; }
+}
+@media (max-width: 760px) {
+  section { padding: 48px 0; }
+  .header-inner { flex-wrap: wrap; gap: 12px; }
+  .primary-nav { order: 3; flex-basis: 100%; overflow-x: auto; }
+  .primary-nav ul { flex-wrap: nowrap; }
+  .search { min-width: 0; flex: 1; }
+  .product-grid { grid-template-columns: repeat(2, 1fr); }
+  .categories { grid-template-columns: repeat(2, 1fr); }
+  .deals { grid-template-columns: 1fr; }
+  .deal-large { grid-column: auto; }
+  .editorial { grid-template-columns: 1fr; }
+  .newsletter { grid-template-columns: 1fr; padding: 28px; }
+  .newsletter .row { flex-direction: column; }
+  .footer-grid { grid-template-columns: 1fr 1fr; }
+}
+@media (max-width: 420px) {
+  .container { padding: 0 16px; }
+  .product-grid { grid-template-columns: 1fr; }
+  .footer-grid { grid-template-columns: 1fr; }
+  .hero-stats { gap: 20px; }
+}
+
+/* Forced colors */
+@media (forced-colors: active) {
+  .btn-primary, .add-btn:hover, .wishlist[aria-pressed="true"] {
+    border: 1px solid ButtonText;
+  }
+  .product-card, .article-card, .deal, .category-card, .hero-card {
+    border-color: ButtonBorder;
+  }
