/* -------------------- Atoms -------------------- */
const Icon = ({ name, size = 18 }) => {
  const paths = {
    search: "M11 19a8 8 0 1 1 5.29-14.01A8 8 0 0 1 11 19Zm10 2-4.35-4.35",
    cart: "M6 6h15l-1.5 9h-12L5 3H2 M9 21a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3Zm9 0a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3Z",
    user: "M20 21a8 8 0 0 0-16 0 M12 13a5 5 0 1 0 0-10 5 5 0 0 0 0 10Z",
    heart: "M12 21s-7-4.5-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 6c-2.5 4.5-9.5 9-9.5 9Z",
    arrow: "M5 12h14 M13 6l6 6-6 6",
  };
  return e("svg", {
    width: size, height: size, viewBox: "0 0 24 24",
    fill: "none", stroke: "currentColor", strokeWidth: "1.8",
    strokeLinecap: "round", strokeLinejoin: "round",
    "aria-hidden": "true", focusable: "false",
  }, e("path", { d: paths[name] }));
};

const Stars = ({ value }) => {
  const full = Math.round(value);
  const str = "★★★★★".slice(0, full) + "☆☆☆☆☆".slice(0, 5 - full);
  return e("span", { className: "stars", "aria-hidden": "true" }, str);
};

