/* -------------------- Featured (with tabs) -------------------- */
function Featured({ onAdd, wishlist, onToggleWish }) {
  const tabs = [
    { id: "trending", label: "Trending" },
    { id: "new", label: "New arrivals" },
    { id: "best", label: "Best sellers" },
  ];
  const [active, setActive] = useState("trending");
  const tabRefs = useRef([]);

  const filtered = useMemo(
    () => PRODUCTS.filter(p => p.group === active),
    [active]
  );

  const onKey = (i) => (ev) => {
    if (ev.key === "ArrowRight" || ev.key === "ArrowLeft") {
      ev.preventDefault();
      const dir = ev.key === "ArrowRight" ? 1 : -1;
      const next = (i + dir + tabs.length) % tabs.length;
      setActive(tabs[next].id);
      tabRefs.current[next]?.focus();
    }
  };

  return e("section", { id: "products", "aria-labelledby": "feat-title" },
    e("div", { className: "container" },
      e("div", { className: "section-head" },
        e("div", null,
          e("h2", { id: "feat-title" }, "Featured products"),
          e("p", null, "Hand-picked favorites from this season's lineup.")
        ),
        e("div", { className: "tabs", role: "tablist", "aria-label": "Featured product filter" },
          tabs.map((t, i) => e("button", {
            key: t.id,
            id: `tab-${t.id}`,
            role: "tab",
            type: "button",
            ref: (el) => (tabRefs.current[i] = el),
            "aria-selected": active === t.id ? "true" : "false",
            "aria-controls": `panel-${t.id}`,
            tabIndex: active === t.id ? 0 : -1,
            className: "tab",
            onClick: () => setActive(t.id),
            onKeyDown: onKey(i),
          }, t.label))
        )
      ),
      e("div", {
        id: `panel-${active}`,
        role: "tabpanel",
        "aria-labelledby": `tab-${active}`,
        className: "product-grid",
      },
        filtered.map(p => e(ProductCard, {
          key: p.id, p, onAdd,
          isWished: wishlist.has(p.id),
          onToggleWish,
        }))
      )
    )
  );
}

/* -------------------- Countdown -------------------- */
function Countdown() {
  const target = useMemo(() => Date.now() + 1000 * 60 * 60 * 47 + 1000 * 23, []);
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const diff = Math.max(0, target - now);
  const h = Math.floor(diff / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  const pad = (n) => String(n).padStart(2, "0");
  const cells = [["Hrs", pad(h)], ["Min", pad(m)], ["Sec", pad(s)]];
  return e("div", {
    className: "countdown",
    role: "timer",
    "aria-live": "off",
    "aria-label": `Sale ends in ${h} hours, ${m} minutes, ${s} seconds`,
  },
    cells.map(([l, n]) => e("div", { key: l, className: "countdown-cell" },
      e("span", { className: "n" }, n),
      e("span", { className: "l" }, l)
    ))
  );
}

