/* -------------------- Newsletter -------------------- */
function Newsletter() {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [status, setStatus] = useState("");
  const inputRef = useRef(null);

  const submit = (ev) => {
    ev.preventDefault();
    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
    if (!valid) {
      setError("Please enter a valid email address.");
      setStatus("");
      inputRef.current?.focus();
      return;
    }
    setError("");
    setStatus(`Thanks! We've added ${email} to the list.`);
    setEmail("");
  };

  return e("section", { "aria-labelledby": "nl-title" },
    e("div", { className: "container" },
      e("div", { className: "newsletter" },
        e("div", null,
          e("h2", { id: "nl-title" }, "Get 10% off your first order"),
          e("p", null, "Subscribe for new drops, restocks, and quiet member sales. No spam — unsubscribe anytime.")
        ),
        e("form", { onSubmit: submit, noValidate: true },
          e("label", { htmlFor: "nl-email", className: "sr-only" }, "Email address (required)"),
          e("div", { className: "row" },
            e("input", {
              id: "nl-email",
              ref: inputRef,
              type: "email",
              placeholder: "you@example.com",
              required: true,
              "aria-required": "true",
              "aria-invalid": error ? "true" : "false",
              "aria-describedby": "nl-help nl-error",
              value: email,
              onChange: (ev) => setEmail(ev.target.value),
              autoComplete: "email",
            }),
            e("button", { type: "submit", className: "btn btn-primary" }, "Subscribe")
          ),
          e("div", { id: "nl-help", className: "field-help" }, "* Required. We'll email a one-time discount code."),
          e("div", { id: "nl-error", className: "field-error", role: "alert" }, error),
          e("div", { className: "newsletter-status", role: "status", "aria-live": "polite" }, status)
        )
      )
    )
  );
}

