/* -------------------- App -------------------- */
function App() {
  const [cart, setCart] = useState(0);
  const [wishlist, setWishlist] = useState(() => new Set());
  const [announce, setAnnounce] = useState("");

  const onAdd = useCallback((p) => {
    setCart(c => c + 1);
    setAnnounce(`${p.title} added to cart.`);
  }, []);

  const onToggleWish = useCallback((id) => {
    setWishlist(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  return e(React.Fragment, null,
    e("a", { href: "#main", className: "skip-link" }, "Skip to main content"),
    e(Header, { cartCount: cart, wishCount: wishlist.size }),
    e("main", { id: "main" },
      e(Hero),
      e(Categories),
      e(Featured, { onAdd, wishlist, onToggleWish }),
      e(Deals),
      e(Editorial),
      e(Newsletter)
    ),
    e(Footer),
    e("div", {
      role: "status",
      "aria-live": "polite",
      className: "sr-only",
    }, announce)
  );
}

